<script setup>
import {ref,onMounted,onBeforeUnmount} from 'vue'
import {getRooms} from '../api/room'
import {listRoomReviews} from '../api/review'
import {validReviewPage,validPublicReview} from '../composables/reviewManagement.js'
import SSelect from '../components/ui/SSelect.vue'
import SButton from '../components/ui/SButton.vue'
import SBanner from '../components/ui/SBanner.vue'
const rooms=ref([]),room=ref(null),snapshot=ref(null),snapshotRoom=ref(null),loading=ref(false),roomLoading=ref(false),error=ref(''),roomError=ref('');let alive=true,ticket=0
onBeforeUnmount(()=>{alive=false;ticket++})
async function loadRooms(){roomLoading.value=true;roomError.value='';try{const {data}=await getRooms();if(!alive)return;if(!Array.isArray(data)||!data.every(r=>Number.isSafeInteger(r.id)&&r.id>0&&typeof r.name==='string'))throw new Error('空间列表不完整');rooms.value=data;if(room.value===null&&data.length){room.value=data[0].id;await load(1)}}catch(e){if(alive)roomError.value=e.message}finally{if(alive)roomLoading.value=false}}
async function load(page=1){const target=Number(room.value);if(!Number.isSafeInteger(target)||target<1){error.value='请先选择真实空间';return}const current=++ticket,params={page,page_size:20};loading.value=true;error.value='';try{const {data}=await listRoomReviews(target,params);if(!alive||current!==ticket)return;if(!validReviewPage(data,params,validPublicReview))throw new Error('空间评价响应不完整，请重试读取');snapshot.value=data;snapshotRoom.value={id:target,name:rooms.value.find(r=>r.id===target)?.name||'空间#'+target}}catch(e){if(alive&&current===ticket)error.value=e.message}finally{if(alive&&current===ticket)loading.value=false}}
onMounted(loadRooms)
</script>
<template><div class="page-view room-reviews"><header class="view-heading"><h1>空间评价</h1><p>校园登录用户可查看公开评价；仅显示匿名评价内容。请勿在自己的评价中填写个人信息。</p></header><section class="card"><form @submit.prevent="load(1)"><label>选择空间<SSelect v-model="room" :options="rooms.map(r=>({value:r.id,label:r.name}))" :disabled="roomLoading"/></label><SButton type="submit" :disabled="!room||loading">查询空间评价</SButton><SButton type="button" :disabled="roomLoading" @click="loadRooms">刷新空间列表</SButton></form><SBanner v-if="roomError" type="error" :title="roomError"/><SBanner v-if="error" type="error" :title="error"/><p v-if="loading" role="status">正在读取所选空间评价；下方保留上次成功数据。</p><p v-if="snapshot">上次成功快照：{{snapshotRoom.name}}（空间#{{snapshotRoom.id}}） · {{snapshot.server_now}} · 页{{snapshot.page}}，公开{{snapshot.total}}条。</p><p v-if="snapshot&&snapshotRoom.id!==Number(room)">下方仍为原空间快照，当前所选空间尚未成功读取。</p><section v-if="snapshot" class="review-cards"><article v-for="item in snapshot.items" :key="item.id"><h3>匿名评价 · {{item.rating}}星</h3><p class="content">{{item.content}}</p><p>评价更新：{{item.updated_at}}</p><template v-if="item.admin_reply"><h4>管理回复</h4><p class="content">{{item.admin_reply}}</p><p>回复登记：{{item.replied_at}}</p></template></article><p v-if="!snapshot.items.length&&!error&&!loading">该次查询暂无公开评价。</p></section><p v-else-if="!loading&&!error">尚未读取公开评价。</p><div v-if="snapshot" class="actions"><SButton :disabled="loading||snapshot.page<=1||snapshotRoom.id!==Number(room)" @click="load(snapshot.page-1)">上一页</SButton><SButton :disabled="loading||snapshot.page*snapshot.page_size>=snapshot.total||snapshotRoom.id!==Number(room)" @click="load(snapshot.page+1)">下一页</SButton><SButton :disabled="loading" @click="load(snapshotRoom.id===Number(room)?snapshot.page:1)">重试/刷新评价</SButton></div></section></div></template>
<style scoped>.room-reviews,.room-reviews .card,.room-reviews form,.room-reviews label,.review-cards{display:grid;gap:16px;min-width:0;overflow-wrap:anywhere}.review-cards article{border-top:1px solid var(--border);padding-top:16px;display:grid;gap:10px}.content{white-space:pre-wrap;overflow-wrap:anywhere}.actions{display:flex;flex-wrap:wrap;gap:12px}</style>
